style.css:
@-moz-document domain("youtube.com") {
.livestream_chat .header {
        background: #fff;
        color: #999;
        box-shadow: 0px 4px 4px -2px rgba(0, 0, 0, 0.4);
    }
    .oz-sprite-conversation-icon {
        background: url('https://kimdongshin.neocities.org/16.png');
        background-size: contain;
    }
    .livestream_chat .header .title:hover .jfk-button {
        background: #fff;
    }
    #live-chat-view-selector-sub-menu {
        background: #fff;
        border: 0;
        box-shadow: rgba(0, 0, 0, 0.14) 0px 2px 2px 0px, rgba(0, 0, 0, 0.12) 0px 1px 5px 0px, rgba(0, 0, 0, 0.2) 0px 3px 1px -2px;
    }
    #live-chat-view-selector-sub-menu .yt-uix-button-menu-item {
        color: #777;
    }
    .yt-uix-button-menu .yt-uix-button-menu-item.selected,
    .yt-uix-button-menu .yt-uix-button-menu-item-highlight .yt-uix-button-menu-item,
    .yt-uix-button-menu .yt-uix-button-menu-item:hover {
        background: #eee;
    }
    .livestream_chat .header .title {
        text-shadow: unset;
    }
    .livestream_chat .header .title .jfk-button .oz-expander-arrow-down,
    [poly-styles] .right_actions > div,
    [poly-styles] .right_actions > button:last-child,
    [poly-styles] .distiller_yt-sb .oz-comment_post-dismiss::after {
        display: none;
    }
    .oz-sprite-conversation-expander {
        background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="rgb(221, 221, 221)"><path fill-rule="evenodd" d="M7 10l5 5 5-5z"/></svg>');
    }
    .livestream_chat .header .oz-sprite-conversation-expander {
        right: 18px;
        width: 26px;
        height: 24px;
        top: 12px;
        transform: unset;
    }
    .livestream_chat .header:hover .oz-sprite-conversation-expander,
    .livestream_chat .header .oz-sprite-conversation-expander {
        filter: unset;
    }
    .livestream_chat .collapsible .live_streamcontent_container {
        background: #eee;
    }
    .livechat_message .chatfly::before {
        left: -9px;
        border: 5px solid #fff;
        border-bottom-color: transparent;
        border-left-color: transparent;
    }
    .livechat_message .chatfly {
        box-shadow: unset;
        border-bottom: 0px solid #C9C9C9;
    }
    .livestream_chat .create_message .distiller_yt-sb .sb_text_input {
        width: 255px;
    }
    @media (max-width: 1495px) {
    .livestream_chat .create_message .distiller_yt-sb .sb_text_input {
        width: 265px;
    }
    }
    .livestream_chat .create_message .distiller_yt-sb .action_bar .jfk-button-action {
        border-color: unset;
        background: unset;
        box-shadow: unset;
    }
    .livestream_chat .create_message .distiller_yt-sb .action_bar .jfk-button-action .jfk-button-text {
        background: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="rgb(117, 117, 117)"><path fill-rule="evenodd" d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg>');
        width: 22px;
        height: 22px;
    }
    .livestream_chat .create_message .distiller_yt-sb .oz-comment_post-dismiss {
        top: 22px;
        right: 80px;
    }
    .livestream_chat .collapsible .create_message .standby .standby_message {
        left: 75px;
        color: #777;
    }
    .sb_text_input {
        padding: 8px 0 7px 10px;
    }
    [poly-comments] .distiller_yt-sb .sb_text_input {
        margin-left: 70px !important;
        margin-top: 8px;
    }
    .cardified-page #watch7-sidebar .live_chat_box_iframe_holder {
        margin-top: -13px;
    }
}
